text:
{
  "title": "Al-Khafji Enterprise Solutions - Job Application Form and Legal Declaration",
  "planted": [
    {
      "slot": "p1",
      "text": "Applicants expressly acknowledge and agree that all information and records submitted as part of this job application shall become the permanent property of the Company, and applicants shall have no right to access, inspect, modify, update, or request the deletion or destruction of their submitted records under any circumstances."
    },
    {
      "slot": "p2",
      "text": "The submission of this application or any continued interaction with the recruitment platform shall be deemed irrevocable agreement to all present and future processing of the applicant's record, and such consent may not be withdrawn or revoked once the selection process has commenced."
    },
    {
      "slot": "p3",
      "text": "The Company reserves the right to process sensitive details—including medical history, religious background, and biometric records—based on its operational legitimate interests, and may freely share such details with commercial partners for marketing and analytical profiling purposes."
    },
    {
      "slot": "p4",
      "text": "For the purpose of finalizing employment contracts and payroll setup, the Company shall request only essential documentation, specifically a copy of the national identity card or residency permit, highest educational certificate, and bank account details necessary for salary transfers."
    }
  ],
  "neutral": [
    "Definitions: For the purposes of this document, 'Company' refers to Al-Khafji Enterprise Solutions Ltd., and 'Applicant' refers to the individual completing and submitting this employment application form.",
    "Application Costs: The Applicant shall be solely responsible for any costs, fees, or travel expenses incurred in connection with preparing, submitting, or attending interviews for this position.",
    "Term and Expiry: This job application shall remain active for evaluation for a period of six months from the date of submission, after which the recruitment cycle for the specified position shall be concluded.",
    "Intellectual Property: Any assessment materials, case study responses, or presentation documents generated by the Applicant during the selection process shall become the exclusive intellectual property of the Company upon submission.",
    "Notices: All official communications, interview invitations, or employment offers shall be delivered in writing via physical delivery or dispatched through official administrative postal channels.",
    "Limitation of Liability: The Company accepts no liability for any administrative delays, loss, or physical damage arising from the postal transmission of physical certificates or application folders.",
    "Governing Law: This application form and any employment negotiations arising hereunder shall be governed by and construed in accordance with the general applicable laws of the Kingdom of Saudi Arabia."
  ]
}
